import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import axios from 'axios';
import { useAuth } from '../contexts/AuthContext';
import toast from 'react-hot-toast';

const ProblemList = () => {
  const [problems, setProblems] = useState([]);
  const [loading, setLoading] = useState(true);
  const { token } = useAuth();
  const navigate = useNavigate();

  useEffect(() => {
    fetchProblems();
  }, []);

  const fetchProblems = async () => {
    try {
      const response = await axios.get('http://localhost:5000/api/problems', {
        headers: { Authorization: `Bearer ${token}` }
      });
      console.log('📚 Problems fetched:', response.data.problems);
      setProblems(response.data.problems || []);
    } catch (error) {
      console.error('Error fetching problems:', error);
      toast.error('Failed to load problems');
    } finally {
      setLoading(false);
    }
  };

  const getDifficultyColor = (difficulty) => {
    switch (difficulty) {
      case 'Easy': return '#28a745';
      case 'Medium': return '#ffc107';
      case 'Hard': return '#dc3545';
      default: return '#6c757d';
    }
  };

  // ✅ Handle problem click with correct ID
  const handleProblemClick = (problemId) => {
    console.log('🖱️ Clicked problem ID:', problemId);
    navigate(`/problems/${problemId}`);
  };

  if (loading) {
    return (
      <div style={styles.loadingContainer}>
        <div className="spinner"></div>
        <p>Loading problems...</p>
      </div>
    );
  }

  return (
    <div style={styles.container}>
      <div style={styles.header}>
        <h1 style={styles.title}>📚 Problems</h1>
        <p style={styles.subtitle}>Solve coding problems and improve your skills</p>
      </div>

      <div style={styles.grid}>
        {problems.length === 0 ? (
          <div style={styles.emptyState}>
            <span style={styles.emptyIcon}>📭</span>
            <p>No problems available</p>
          </div>
        ) : (
          problems.map((problem) => (
            <div
              key={problem._id}
              style={styles.card}
              onClick={() => handleProblemClick(problem._id)} // ✅ Pass correct ID
            >
              <div style={styles.cardHeader}>
                <h3 style={styles.cardTitle}>{problem.title}</h3>
                <span style={{
                  ...styles.difficultyBadge,
                  backgroundColor: getDifficultyColor(problem.difficulty),
                  color: problem.difficulty === 'Medium' ? '#333' : 'white'
                }}>
                  {problem.difficulty || 'Easy'}
                </span>
              </div>
              <p style={styles.cardDescription}>
                {problem.description?.substring(0, 120)}...
              </p>
              <div style={styles.cardFooter}>
                <span style={styles.cardId}>#{problem._id}</span>
                <span style={styles.cardAction}>Solve →</span>
              </div>
            </div>
          ))
        )}
      </div>
    </div>
  );
};

const styles = {
  container: {
    padding: '30px',
    maxWidth: '1200px',
    margin: '0 auto',
    minHeight: '100vh',
    background: '#f0f2f5',
  },
  header: {
    marginBottom: '30px',
  },
  title: {
    fontSize: '28px',
    fontWeight: 700,
    color: '#1a1a2e',
    marginBottom: '8px',
  },
  subtitle: {
    fontSize: '16px',
    color: '#666',
  },
  grid: {
    display: 'grid',
    gridTemplateColumns: 'repeat(auto-fill, minmax(320px, 1fr))',
    gap: '20px',
  },
  card: {
    background: 'white',
    padding: '24px',
    borderRadius: '12px',
    boxShadow: '0 2px 8px rgba(0,0,0,0.06)',
    cursor: 'pointer',
    transition: 'all 0.3s ease',
    border: '1px solid #e8e8e8',
  },
  cardHeader: {
    display: 'flex',
    justifyContent: 'space-between',
    alignItems: 'flex-start',
    marginBottom: '12px',
  },
  cardTitle: {
    fontSize: '18px',
    fontWeight: 600,
    color: '#1a1a2e',
    margin: 0,
    flex: 1,
    marginRight: '10px',
  },
  difficultyBadge: {
    padding: '4px 14px',
    borderRadius: '20px',
    fontSize: '12px',
    fontWeight: 600,
    whiteSpace: 'nowrap',
  },
  cardDescription: {
    color: '#666',
    fontSize: '14px',
    lineHeight: '1.6',
    marginBottom: '16px',
  },
  cardFooter: {
    display: 'flex',
    justifyContent: 'space-between',
    alignItems: 'center',
    paddingTop: '12px',
    borderTop: '1px solid #f0f0f0',
  },
  cardId: {
    fontSize: '13px',
    color: '#999',
  },
  cardAction: {
    fontSize: '14px',
    fontWeight: 600,
    color: '#6C63FF',
  },
  loadingContainer: {
    display: 'flex',
    flexDirection: 'column',
    alignItems: 'center',
    justifyContent: 'center',
    minHeight: '60vh',
  },
  emptyState: {
    gridColumn: '1 / -1',
    textAlign: 'center',
    padding: '60px 20px',
    color: '#999',
  },
  emptyIcon: {
    fontSize: '48px',
    display: 'block',
    marginBottom: '12px',
  },
};

export default ProblemList;
